const incoming = $input.first().json;
const body = incoming.body || incoming;
const payload = typeof body === 'string' ? JSON.parse(body) : body;
const data = payload.quote || payload;

const serviceTypes = {
  full: { label: 'Trasloco chiavi in mano', detail: 'Smontaggio, imballaggio, carico, trasporto, scarico e rimontaggio', base: 1180 },
  standard: { label: 'Trasloco standard', detail: 'Carico, trasporto, scarico e supporto operativo', base: 780 },
  transport: { label: 'Solo trasporto', detail: 'Trasporto con furgone e conducente', base: 420 },
  lift: { label: 'Noleggio autoscala', detail: 'Autoscala con operatore per movimentazione esterna', base: 350 },
  disposal: { label: 'Sgombero / smaltimento', detail: 'Ritiro e conferimento materiale ingombrante', base: 520 },
};

const extras = [
  ['packing', 'Imballaggio fragili', 'Materiali e protezione oggetti delicati', 180],
  ['assembly', 'Smontaggio e rimontaggio', 'Mobili principali esclusa cucina complessa', 260],
  ['liftAccess', 'Autoscala', 'Accesso esterno o piano alto senza ascensore', 220],
  ['permits', 'Permessi suolo pubblico', 'Stima gestione area carico/scarico', 95],
  ['storage', 'Deposito mobili', 'Prima settimana di deposito', 160],
  ['urgent', 'Urgenza', 'Organizzazione con breve preavviso', 120],
];

function num(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function money(value) {
  return new Intl.NumberFormat('it-IT', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(Math.max(0, value));
}

function dateText(date) {
  return new Intl.DateTimeFormat('it-IT', { day: '2-digit', month: '2-digit', year: 'numeric', timeZone: 'Europe/Rome' }).format(date);
}

function addDays(date, days) {
  const copy = new Date(date.getTime());
  copy.setDate(copy.getDate() + num(days, 15));
  return copy;
}

function floorCost() {
  let total = 0;
  if (data.originElevator === 'no') total += Math.max(0, num(data.originFloor)) * 55;
  if (data.destElevator === 'no') total += Math.max(0, num(data.destFloor)) * 55;
  return total;
}

const selected = serviceTypes[data.serviceType] || serviceTypes.standard;
const lineItems = [
  { label: selected.label, detail: selected.detail, amount: selected.base },
  { label: 'Volume stimato', detail: `${num(data.volume)} mc`, amount: num(data.volume) * 22 },
  { label: 'Distanza', detail: `${num(data.distance)} km stimati`, amount: num(data.distance) * 1.8 },
  { label: 'Scatole', detail: `${num(data.boxes)} colli indicativi`, amount: num(data.boxes) * 2.5 },
];

const accessCost = floorCost();
if (accessCost > 0) {
  lineItems.push({ label: 'Accesso piani', detail: 'Maggiorazione per piano senza ascensore', amount: accessCost });
}

for (const [key, label, detail, amount] of extras) {
  if (data[key] === true || data[key] === 'true' || data[key] === 'on') lineItems.push({ label, detail, amount });
}

const discount = num(data.discount);
if (discount > 0) lineItems.push({ label: 'Sconto commerciale', detail: 'Applicato in fase di revisione', amount: -discount });

const subtotal = Math.max(0, lineItems.reduce((sum, item) => sum + item.amount, 0));
const vatRate = num(data.vatMode, 22);
const vat = subtotal * (vatRate / 100);
const total = subtotal + vat;

const riskFlags = [];
if (data.originElevator === 'no' && num(data.originFloor) >= 3) riskFlags.push('Partenza al terzo piano o superiore senza ascensore: verificare accesso e autoscala.');
if (data.destElevator === 'no' && num(data.destFloor) >= 3) riskFlags.push('Arrivo al terzo piano o superiore senza ascensore: verificare accesso e autoscala.');
if (data.liftAccess || data.serviceType === 'lift') riskFlags.push('Autoscala richiesta: controllare spazio di manovra, balcone/finestra e permessi.');
if (data.permits) riskFlags.push('Permessi suolo pubblico inclusi come stima: confermare comune e tempistiche.');
if (data.urgent) riskFlags.push('Richiesta urgente: confermare disponibilita squadra e mezzi.');
if (num(data.volume) >= 35) riskFlags.push('Volume elevato: valutare sopralluogo prima di inviare offerta finale.');
if (num(data.distance) >= 150) riskFlags.push('Tratta lunga: verificare tempi guida, carburante, pedaggi e pernottamenti.');

const now = new Date();
const dateCode = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Rome' }).format(now).replaceAll('-', '');
const executionSuffix = String($execution.id || Date.now()).replace(/\D/g, '').slice(-4).padStart(4, '0');
const quoteNumber = data.quoteNumber || `ATL-${dateCode}-${executionSuffix}`;
const validUntil = dateText(addDays(now, data.validDays));
const firstName = String(data.clientName || 'Cliente').trim().split(/\s+/)[0] || 'Cliente';
const totalText = money(total);

const emailBody = `Gentile ${firstName},\n\nin allegato trova il preventivo ${quoteNumber} per il servizio di trasloco richiesto.\n\nIl totale stimato e ${totalText} IVA inclusa. Il preventivo resta valido fino al ${validUntil}.\n\nPer confermare o modificare il servizio puo rispondere direttamente a questa email oppure contattarci al numero 039 2001106.\n\nCordiali saluti,\nAtlantico Traslochi SRL`;

return [{
  json: {
    ok: true,
    source: 'n8n',
    status: riskFlags.length ? 'needs_review' : 'ready_to_send',
    workflowName: 'Atlantico Preventivi Prototype API',
    executionId: $execution.id,
    receivedAt: now.toISOString(),
    quoteNumber,
    validUntil,
    customer: {
      name: data.clientName || '',
      email: data.clientEmail || '',
      phone: data.clientPhone || '',
    },
    route: {
      origin: data.origin || '',
      destination: data.destination || '',
      moveDate: data.moveDate || '',
    },
    lineItems,
    totals: {
      subtotal,
      vatRate,
      vat,
      total,
      subtotalText: money(subtotal),
      vatText: money(vat),
      totalText,
    },
    riskFlags,
    email: {
      to: data.clientEmail || '',
      subject: `Preventivo ${quoteNumber} - Atlantico Traslochi`,
      body: emailBody,
      attachmentName: `${quoteNumber.toLowerCase()}-${String(data.clientName || 'cliente').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}.pdf`,
    },
  }
}];
